CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE tenants(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),name TEXT,email TEXT,settings JSONB NOT NULL DEFAULT '{}');
CREATE TABLE leads(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),name TEXT,phone TEXT,email TEXT,location TEXT,source TEXT,product TEXT,stage TEXT DEFAULT 'new',won_at TIMESTAMP,lost_at TIMESTAMP,tags TEXT[],ai_paused BOOLEAN DEFAULT false,opted_out BOOLEAN DEFAULT false,automation_unresponsive BOOLEAN DEFAULT false,whatsapp_opt_in_at TIMESTAMP,whatsapp_opt_in_source TEXT);
CREATE TABLE lead_stages(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),name TEXT,is_won BOOLEAN DEFAULT false,is_lost BOOLEAN DEFAULT false);
CREATE TABLE lead_followups(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),lead_id UUID REFERENCES leads(id),followup_type TEXT,is_completed BOOLEAN DEFAULT false,dismissed_at TIMESTAMP);
CREATE TABLE automation_sequences(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),name TEXT,description TEXT,is_active BOOLEAN DEFAULT true,created_at TIMESTAMP DEFAULT now(),updated_at TIMESTAMP DEFAULT now());
CREATE TABLE automation_sequence_steps(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),sequence_id UUID REFERENCES automation_sequences(id),step_order INT,delay_minutes INT DEFAULT 0,channel TEXT DEFAULT 'whatsapp',message TEXT,approved_template_name TEXT,ai_generated BOOLEAN DEFAULT false,ai_instructions TEXT,email_subject TEXT);
CREATE TABLE automation_rules(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),name TEXT,trigger_type TEXT,sequence_id UUID REFERENCES automation_sequences(id),is_active BOOLEAN DEFAULT true,campaign_id UUID,source_value TEXT,status_value TEXT,stage_name TEXT);
CREATE TABLE automation_enrollments(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),lead_id UUID REFERENCES leads(id),sequence_id UUID REFERENCES automation_sequences(id),rule_id UUID,current_step INT DEFAULT 0,status VARCHAR(20) DEFAULT 'active',enrolled_at TIMESTAMP DEFAULT now(),next_send_at TIMESTAMP DEFAULT now(),completed_at TIMESTAMP,cancelled_at TIMESTAMP,cancelled_reason VARCHAR(30),UNIQUE(tenant_id,lead_id,sequence_id));
CREATE TABLE whatsapp_messages(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),tenant_id UUID REFERENCES tenants(id),lead_id UUID REFERENCES leads(id),direction TEXT,message TEXT,message_type TEXT,template_name TEXT,wa_message_id TEXT,status TEXT,is_automated BOOLEAN,is_ai_generated BOOLEAN,sent_at TIMESTAMP DEFAULT now());
CREATE TABLE whatsapp_template_media(tenant_id UUID,template_name TEXT,language TEXT,media_type TEXT,media_url TEXT);
CREATE TABLE lead_activities(tenant_id UUID,lead_id UUID,activity_type TEXT,title TEXT,description TEXT,created_by UUID);
